1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Derives an owner's {@code identityKey}, the single value all duplicate detection is now
7	 * expressed through:
8	 * {@code normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty)}.
9	 *
10	 * <p>The components are taken from the owner as already canonicalised earlier in the create
11	 * pipeline: the telephone in E.164 form (see {@link TelephoneE164}), the email lower-cased,
12	 * and the shared {@code householdId} once {@link AssignHousehold} has assigned it. Because the
13	 * telephone is part of the key, two members of the same household (same {@code householdId})
14	 * with different telephones have different identity keys; only an exact whole-key match is a
15	 * duplicate.
16	 */
17	public final class OwnerIdentity {
18	
19	    private OwnerIdentity() {
20	    }
21	
22	    public static String of(Owner owner) {
23	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
24	        String email = (owner.getEmail() == null || owner.getEmail().isBlank()) ? "" : owner.getEmail();
25	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
26	        return telephone + "|" + email + "|" + householdId;
27	    }
28	}
