1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * The consolidated duplicate check, rejecting a create with 409 in either of two ways:
11	 *
12	 * <ul>
13	 * <li><b>Full-identity duplicate</b> — the whole {@code identityKey} (see {@link OwnerIdentity},
14	 * {@code normalizedTelephone|email|householdId}) equals an existing owner's. Because the telephone
15	 * is part of the key, two members of the same household with different telephones have different
16	 * keys; only an exact whole-key match collides. This always applies, even when
17	 * {@code sharesHousehold} is set.</li>
18	 * <li><b>Household duplicate</b> — the new owner's computed {@code householdId} (keyed on
19	 * lastName + postcode; see {@link AssignHousehold}) already identifies an existing owner, i.e. a
20	 * second owner sharing lastName and postcode. This is blocked <em>unless</em> the request opts in
21	 * with {@code sharesHousehold} (created as a declared household member) or the new owner carries a
22	 * distinct email — an email that no colliding household member shares — which identifies it as a
23	 * separate person joining the household rather than a re-registration.</li>
24	 * </ul>
25	 *
26	 * <p>Runs after {@link AssignHousehold} so the new owner's {@code householdId} is set before it is
27	 * compared. The new owner is not yet saved, so it is not among the existing owners compared here.
28	 */
29	public class EnsureUniqueIdentity {
30	
31	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository)
32	            throws DuplicateIdentityException {
33	        String identityKey = OwnerIdentity.of(owner);
34	        String householdId = owner.getHouseholdId();
35	        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
36	        for (Owner existing : ownerRepository.findAll()) {
37	            if (existing.isDeleted()) {
38	                continue; // a soft-deleted owner no longer blocks a create
39	            }
40	            if (identityKey.equals(OwnerIdentity.of(existing))) {
41	                throw new DuplicateIdentityException(identityKey);
42	            }
43	            if (!sharesHousehold && householdId != null
44	                    && householdId.equals(existing.getHouseholdId())
45	                    && !distinctEmail(owner, existing)) {
46	                throw new DuplicateIdentityException(identityKey);
47	            }
48	        }
49	    }
50	
51	    /** Whether the new owner carries a non-blank email that the colliding household member does not
52	     *  share (compared case-insensitively) — a personal identifier marking it a separate person. */
53	    private static boolean distinctEmail(Owner owner, Owner existing) {
54	        String email = owner.getEmail();
55	        if (email == null || email.isBlank()) {
56	            return false;
57	        }
58	        return !email.equalsIgnoreCase(existing.getEmail());
59	    }
60	}
