1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	
10	/**
11	 * Assigns the owner's soft-match duplicate signal. A create request that clears the hard
12	 * duplicate check (see {@link EnsureUniqueIdentity}) may still resemble an existing owner: when
13	 * the new owner shares an existing owner's lastName (compared case-insensitively with collapsed
14	 * whitespace) and postcode while carrying a different telephone, it is still created but flagged
15	 * with {@code possibleDuplicate} true and {@code possibleDuplicateOf} set to that existing
16	 * owner's id. Otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} null.
17	 *
18	 * <p>A declared household member ({@code sharesHousehold} true) is never flagged: it shares an
19	 * existing member's lastName and postcode by design, so it is a known household member rather than
20	 * a suspected duplicate. (A same lastName + postcode owner that did <em>not</em> declare the
21	 * household is rejected as a household duplicate by {@link EnsureUniqueIdentity} unless it carries a
22	 * distinct email; such an email-distinguished owner does reach this step and, having a different
23	 * telephone, is flagged as a possible duplicate of the existing member.)
24	 *
25	 * <p>Only owners with a postcode participate: a match requires both postcodes to be present and
26	 * equal. When several existing owners match, the earliest (lowest id) is reported. Runs before
27	 * {@code save}, so the new owner is not compared against itself.
28	 */
29	public class AssignPossibleDuplicate {
30	
31	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
32	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
33	            owner.setPossibleDuplicate(false);
34	            owner.setPossibleDuplicateOf(null);
35	            return; // a declared household member is not a suspected duplicate
36	        }
37	        String lastName = normalize(owner.getLastName());
38	        String postcode = owner.getPostcode();
39	        String telephone = owner.getTelephone();
40	        Owner match = null;
41	        if (postcode != null && !postcode.isBlank()) {
42	            for (Owner existing : ownerRepository.findAll()) {
43	                if (existing.isDeleted()) {
44	                    continue; // a soft-deleted owner is not a soft-match candidate
45	                }
46	                if (lastName.equals(normalize(existing.getLastName()))
47	                        && postcode.equals(existing.getPostcode())
48	                        && !equalsTelephone(telephone, existing.getTelephone())) {
49	                    if (match == null || lessThan(existing.getId(), match.getId())) {
50	                        match = existing;
51	                    }
52	                }
53	            }
54	        }
55	        if (match != null) {
56	            owner.setPossibleDuplicate(true);
57	            owner.setPossibleDuplicateOf(match.getId());
58	        }
59	        else {
60	            owner.setPossibleDuplicate(false);
61	            owner.setPossibleDuplicateOf(null);
62	        }
63	    }
64	
65	    private static boolean equalsTelephone(String a, String b) {
66	        return a == null ? b == null : a.equals(b);
67	    }
68	
69	    private static boolean lessThan(Integer a, Integer b) {
70	        if (a == null) {
71	            return false;
72	        }
73	        if (b == null) {
74	            return true;
75	        }
76	        return a < b;
77	    }
78	
79	    /** Case-insensitive with collapsed whitespace: trim, fold internal whitespace runs to a
80	     *  single space, and lower-case. */
81	    private static String normalize(String value) {
82	        if (value == null) {
83	            return "";
84	        }
85	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
86	    }
87	}
