1	package org.springframework.samples.petclinic.rest.escalation;
2	
3	/**
4	 * Thrown when a create request's whole derived {@code identityKey}
5	 * (normalizedTelephone + '|' + email + '|' + householdId) already identifies another owner.
6	 * Handled by {@link DuplicateIdentityExceptionHandler}, which responds 409.
7	 */
8	public class DuplicateIdentityException extends Exception {
9	
10	    public DuplicateIdentityException(String identityKey) {
11	        super("Owner identity already in use: " + identityKey);
12	    }
13	}
