1	package org.springframework.samples.petclinic.acceptance;
2	
3	import org.junit.jupiter.api.Tag;
4	import org.junit.jupiter.api.Test;
5	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
6	import static org.junit.jupiter.api.Assertions.assertTrue;
7	import tools.jackson.databind.JsonNode;
8	import tools.jackson.databind.node.ObjectNode;
